presetParts.perVertex:
thresh = above(bass_att,thresh)*2+(1-above(bass_att,thresh))*((thresh-1.3)*0.96+1.3);
dx_r = equal(thresh,2)*0.015*sin(5*time)+(1-equal(thresh,2))*dx_r;
dy_r = equal(thresh,2)*0.015*sin(6*time)+(1-equal(thresh,2))*dy_r;

sib = 0.25*cos((bass_att*3)*sin(4*time));
sit = 0.25*sin((treb_att*3)*sin(4*time));
sim = 0.25*cos((mid_att*3)*sin(4*time));
fx = 0.25*sin(bass_att*rad)-0.4*rad*cos(4*time);
fy = 0.25*cos(mid_att*rad)-0.4*rad*sin(4*time);

bruch = fx*((sit+sib+sim)/2)*below(rad,sin(fy*time));
brach = fy*((sit*sib*sim)*2)*above(rad,cos(fx*time));

zoom = zoom + abs(bruch+brach*2)*(above(rad,0.5*sin(sit)));
zoom = zoom - abs(bruch+brach*2)*(below(rad,0.5*sin(sib)));
zoom = zoom + abs(bruch+brach*2)*(above(rad,0.5*sin(sim)));
zoom = zoom - abs(bruch+brach*2)*(below(rad,0.5*sin(fx/fy)));
zoom = zoom + 0.05*cos(thresh*bruch-(sin(6*bass_att)-rad));
